    const float e = thunkEec73f0()(blended);              // 0xbc7b925  call 0xEEC73F0
    const std::int64_t idxE = rnd(e);                     // 0xbc7b934..0xbc7b94d        rdx = rnd(e)
    if (idxE >= kIndexLimit) {                            // 0xbc7b950  cmp rdx,0x65
                                                            // 0xbc7b954  jae  0xBC7BA55
