    uint32_t A = self->writeIdx;      // edx = [rsi+0x783C]
    uint32_t c = self->cursor;        // ecx = [rsi+0x7844]
    uint32_t d = A - c;              // sub edx,ecx
    uint32_t eax = d + (static_cast<uint32_t>(static_cast<int32_t>(d) >> 31) & M); // sar/and/add
