    void* const a1 = ctx;    // RDX = ctx (ExecCtx*)

    // 0x5699e43  mov r8,rcx   (r8 == a0 throughout)

    // PassArgs on the stack at [rbp-0x18, rbp): { arg0, view, ctrl }
