// Reads: task+0x100 (arg0), task+0x108 (viewRef), task+0x110 (ctrl), *ctrl (vfptr),
//   ctrl+0x08 (uses), ctrl+0x0C (weaks), *ctrl vfptr[0] (dispose), *ctrl vfptr[1] (destroy),
