//   +0x00: Node* next   (next node, or null)
//   +0x10: union { char* heapData; char ssoBuffer[0x18]; }  (data pointer or SSO buffer)
//   +0x20: uint64_t size   (string length)
//   +0x28: uint64_t capacity  (capacity; < 0x10 indicates SSO)
